// Services/Export/MetadataScrubber.swift

import UIKit

struct MetadataScrubber {
    static func scrubMetadata(from image: UIImage) -> UIImage? {
        guard let imageData = image.jpegData(compressionQuality: 1.0),
              let source = CGImageSourceCreateWithData(imageData as CFData, nil) else {
            return nil
        }

        // Create a mutable copy of the image properties
        if let imageProperties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [String: Any] {
            var options = [CFString: Any]()
            options[kCGImagePropertyExifDictionary] = [:]
            options[kCGImagePropertyTIFFDictionary] = [:]

            // Create a new image source without the metadata
            let scrubbedData = NSMutableData()
            guard let destination = CGImageDestinationCreateWithData(scrubbedData, kUTTypeJPEG, 1, nil) else {
                return nil
            }

            if let cgImage = CGImageSourceCreateImageAtIndex(source, 0, options as CFDictionary) {
                CGImageDestinationAddImage(destination, cgImage, [:])
                if CGImageDestinationFinalize(destination) {
                    return UIImage(data: scrubbedData as Data)
                }
            }
        }

        return nil
    }
}
